def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Assuming the plugin spec is in a file named 'plugin_spec.json' within the plugin_dir
    spec_file_path = os.path.join(plugin_dir, 'plugin_spec.json')

    if not os.path.exists(spec_file_path):
        raise FileNotFoundError(f"Plugin spec file not found at {spec_file_path}")

    with open(spec_file_path, 'r') as file:
        plugin_spec = json.load(file)

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(plugin_spec)
```

This function assumes that the plugin specification is stored in a JSON file named `plugin_spec.json` within the provided `plugin_dir`. It reads the JSON file, flattens the dictionary, and returns the flattened dictionary. Adjust the file name and path as necessary to fit your specific use case.
